  accent2: "3B82F6",      // blue
  accent3: "10B981",      // emerald
  accent4: "8B5CF6",      // violet
  accent5: "EF4444",      // red
  accent6: "EC4899",      // pink
  lightText: "F8FAFC",    // near-white
  mutedText: "94A3B8",    // muted slate
  cardBg: "1E293B",       // card background
  white: "FFFFFF",
  chartBar1: "F59E0B",
  chartBar2: "3B82F6",
  chartBar3: "10B981",
  chartBar4: "8B5CF6",
  chartBar5: "EF4444",
};

