      { text: "UI library boom", options: { bullet: true, breakLine: true, color: C.lightText } },
      { text: "PrimeVue, shadcn-vue signal growing ecosystem confidence", options: { bullet: true, breakLine: true, color: C.mutedText, fontSize: 10 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Active release cycle", options: { bullet: true, breakLine: true, color: C.lightText } },
      { text: "Regular performance improvements (Daniel Roe, Nuxt lead)", options: { bullet: true, color: C.mutedText, fontSize: 10 } },
    ], {
      x: 6.1, y: 2.2, w: 3.3, h: 2.3,
      fontFace: FONTS.body, fontSize: 12, margin: 0
    });
  }

  // ========== SLIDE 7: Emerging Themes ==========
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };

    slide.addText("Emerging Themes Shaping 2024", {
      x: 0.6, y: 0.3, w: 9, h: 0.6,
      fontFace: FONTS.heading, fontSize: 26, color: C.lightText, bold: true, margin: 0
    });

    slide.addText("AI tools, desktop apps, and browser-based innovation dominate", {
      x: 0.6, y: 0.85, w: 9, h: 0.35,
      fontFace: FONTS.body, fontSize: 13, color: C.mutedText, margin: 0
    });

    // 3-column layout for themes
    const themes = [
      {
        icon: FaBrain, iconColor: "#F59E0B", title: "AI-Powered Tools",
        color: C.accent,
        items: [
          { name: "n8n", val: "+17.0k", desc: "Workflow automation with native AI" },
          { name: "Flowise", val: "+14.5k", desc: "Visual LLM flow builder" },
          { name: "Supabase", val: "+14.5k", desc: "Open-source BaaS with AI" },
          { name: "AFFiNE", val: "+19.6k", desc: "AI-powered knowledge base" },
        ]
      },
      {
        icon: FaDesktop, iconColor: "#3B82F6", title: "Desktop & Mobile",
        color: C.accent2,
        items: [
          { name: "Tauri", val: "+15.9k", desc: "Lighter Electron alternative" },
          { name: "Excalidraw", val: "+27.0k", desc: "Whiteboard app" },
          { name: "Bruno", val: "+18.7k", desc: "API testing IDE" },
        ]
      },
      {
        icon: FaGlobe, iconColor: "#10B981", title: "Browser Innovation",
        color: C.accent3,
        items: [
          { name: "PGlite", val: "", desc: "Postgres via WebAssembly" },
          { name: "WebVM", val: "", desc: "VM running in browser" },
          { name: "htmx", val: "+16.8k", desc: "HTML-first interactivity" },
        ]
      },
    ];

    for (let i = 0; i < themes.length; i++) {
      const t = themes[i];
      const cx = 0.4 + i * 3.2;
      const cy = 1.4;
      const cw = 3.0;

      // Card bg
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cy, w: cw, h: 3.8,
        fill: { color: C.cardBg }, shadow: mkShadow()
      });

      // Top accent bar
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cy, w: cw, h: 0.06,
        fill: { color: t.color }
      });

      // Icon
      const themeIcon = await iconToBase64Png(t.icon, t.iconColor, 256);
      slide.addImage({ data: themeIcon, x: cx + 0.2, y: cy + 0.25, w: 0.35, h: 0.35 });

      // Title
      slide.addText(t.title, {
        x: cx + 0.65, y: cy + 0.25, w: 2.1, h: 0.35,
        fontFace: FONTS.heading, fontSize: 14, color: C.lightText, bold: true, valign: "middle", margin: 0
      });

      // Items
      t.items.forEach((item, j) => {
        const iy = cy + 0.85 + j * 0.72;
        slide.addText(item.name, {
          x: cx + 0.2, y: iy, w: 1.4, h: 0.3,
          fontFace: FONTS.body, fontSize: 12, color: C.lightText, bold: true, margin: 0
        });
        if (item.val) {
          slide.addText(item.val, {
            x: cx + 1.6, y: iy, w: 1.1, h: 0.3,
            fontFace: FONTS.body, fontSize: 11, color: t.color, bold: true, align: "right", valign: "middle", margin: 0
          });
        }
        slide.addText(item.desc, {
          x: cx + 0.2, y: iy + 0.28, w: 2.6, h: 0.3,
          fontFace: FONTS.body, fontSize: 9, color: C.mutedText, margin: 0
        });
      });
    }
  }

  // ========== SLIDE 8: Key Takeaways ==========
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };

    slide.addText("Key Takeaways: What 2024 Tells Us", {
      x: 0.6, y: 0.3, w: 9, h: 0.6,
      fontFace: FONTS.heading, fontSize: 26, color: C.lightText, bold: true, margin: 0
    });

    slide.addText("Actionable insights for JavaScript in 2025 and beyond", {
      x: 0.6, y: 0.85, w: 9, h: 0.35,
      fontFace: FONTS.body, fontSize: 13, color: C.mutedText, margin: 0
    });

    const takeaways = [
      {
        num: "1", color: C.accent,
        title: "Component ownership beats imports",
        body: "shadcn/ui\u2019s copy-paste model proved its staying power for a second year, reaching 77.5k total stars. Consider adopting similar ownership patterns in your design systems."
      },
      {
        num: "2", color: C.accent2,
        title: "HTML-first is serious",
        body: "htmx overtook React as #1 framework by stars added, validating server-driven, low-JavaScript architectures. Evaluate htmx for content-heavy and progressive enhancement use cases."
      },
      {
        num: "3", color: C.accent3,
        title: "React is becoming a framework spec",
        body: "With Server Components and Server Functions in React 19, frameworks now interpret React\u2019s primitives differently. Choose your React framework deliberately \u2014 they\u2019re no longer interchangeable."
      },
      {
        num: "4", color: C.accent4,
        title: "AI integration is table stakes",
        body: "4 of the top 10 projects have significant AI capabilities. If your tooling doesn\u2019t have an AI story, you\u2019re falling behind."
      },
      {
        num: "5", color: C.accent6,
        title: "Vue\u2019s ecosystem signals maturity",
        body: "A wave of quality UI libraries and the Vue 3.5 reactivity overhaul show a confident ecosystem. Vue is a strong bet for new projects in 2025."
      },
    ];

    takeaways.forEach((t, i) => {
      const rowY = 1.35 + i * 0.82;
      const cardW = 8.8;

      // Card
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.6, y: rowY, w: cardW, h: 0.72,
        fill: { color: C.cardBg }
      });

      // Left accent
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.6, y: rowY, w: 0.06, h: 0.72,
        fill: { color: t.color }
      });

      // Number circle
      slide.addShape(pres.shapes.OVAL, {
        x: 0.85, y: rowY + 0.16, w: 0.4, h: 0.4,
        fill: { color: t.color }
      });
      slide.addText(t.num, {
        x: 0.85, y: rowY + 0.16, w: 0.4, h: 0.4,
        fontFace: FONTS.heading, fontSize: 16, color: C.white,
        bold: true, align: "center", valign: "middle", margin: 0
      });

      // Title
      slide.addText(t.title, {
        x: 1.45, y: rowY + 0.04, w: 7.5, h: 0.3,
        fontFace: FONTS.heading, fontSize: 14, color: C.lightText, bold: true, valign: "middle", margin: 0
      });

      // Body
      slide.addText(t.body, {
        x: 1.45, y: rowY + 0.34, w: 7.5, h: 0.35,
        fontFace: FONTS.body, fontSize: 10, color: C.mutedText, valign: "top", margin: 0
      });
    });

    // Bottom bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 5.3, w: 10, h: 0.325,
      fill: { color: C.darkBg2 }
    });

    slide.addText("Source: JavaScript Rising Stars 2024  |  risingstars.js.org/2024", {
      x: 0.6, y: 5.3, w: 9, h: 0.325,
      fontFace: FONTS.body, fontSize: 10, color: C.mutedText, valign: "middle", margin: 0
    });
  }

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

main().catch(err => { console.error(err); process.exit(1); });

